import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 3

def design(feats):
    # Identify strong univariate predictors
    strong_uni = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        tstat, _ = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if abs(tstat) > 3.0:
            strong_uni.append((abs(tstat), fid))

    strong_uni.sort(reverse=True)
    strong_uni_ids = [fid for _, fid in strong_uni[:10]]

    # Check for product terms among top features
    candidates = []
    for i, fid1 in enumerate(strong_uni_ids):
        for j, fid2 in enumerate(strong_uni_ids):
            if i >= j:
                continue
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            prod = feats.x[:, col1] * feats.x[:, col2]
            tstat, _ = stats.ttest_ind(prod[feats.y==1], prod[feats.y==0])
            if abs(tstat) > 2.5:
                candidates.append((abs(tstat), fid1, fid2))

    candidates.sort(reverse=True)

    # Look for correlated pairs that might suggest interaction
    correlations = []
    for i, fid1 in enumerate(feats.ids):
        for j, fid2 in enumerate(feats.ids):
            if i >= j:
                continue
            col1 = feats.column(fid1)
            col2 = feats.column(fid2)
            corr = np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0, 1]
            if abs(corr) >= 0.6:
                correlations.append((abs(corr), fid1, fid2))

    correlations.sort(reverse=True)

    # Prioritize product terms over correlations
    if candidates:
        best_product = candidates[0]
        return Design(
            drivers=(best_product[1], best_product[2]),
            columns=(best_product[1], best_product[2]),
            products=((best_product[1], best_product[2]),),
            loadings={}
        )

    # If no product found, try to find strong single predictors
    if strong_uni:
        drivers = tuple([fid for _, fid in strong_uni[:MAX_DRIVERS]])
        return Design(
            drivers=drivers,
            columns=drivers,
            products=(),
            loadings={}
        )

    # No mechanism found
    return Design(
        drivers=(),
        columns=(),
        products=(),
        loadings={}
    )

